export const getGetEventDeliveriesUrl = (eventId: string,) => {


  

  return `/events/${eventId}/deliveries`
}

export const getEventDeliveries = async (eventId: string, options?: RequestInit): Promise<getEventDeliveriesResponse> => {
  
  return customInstance<getEventDeliveriesResponse>(getGetEventDeliveriesUrl(eventId),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





export const getGetEventDeliveriesQueryKey = (eventId: string,) => {
    return [
    `/events/${eventId}/deliveries`
    ] as const;
    }

    
